#!/usr/bin/env node
/**
 * Generates `src/data/moon-orbits.generated.ts` from the parsed JPL
 * "Planetary Satellite Mean Elements" table (reference/satellite-elements.json).
 *
 * The generated file is committed so that the app builds without network
 * access; re-run this script only when the reference data changes.
 *
 * Usage: node scripts/gen-moon-orbits.mjs
 */
import { readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const AU_KM = 149_597_870.7;
const J2000 = 2_451_545.0;

const ref = JSON.parse(await readFile(resolve(ROOT, 'reference/satellite-elements.json'), 'utf8'));
const sats = ref.satellites;

/** Curated list: which satellites Solar renders, and where they belong. */
const SELECTION = [
  ['Moon', 'earth', '月球', true],
  ['Phobos', 'mars', '火卫一（福波斯）'],
  ['Deimos', 'mars', '火卫二（得摩斯）'],
  ['Io', 'jupiter', '木卫一（伊奥）'],
  ['Europa', 'jupiter', '木卫二（欧罗巴）'],
  ['Ganymede', 'jupiter', '木卫三（盖尼米德）'],
  ['Callisto', 'jupiter', '木卫四（卡利斯托）'],
  ['Mimas', 'saturn', '土卫一（弥玛斯）'],
  ['Enceladus', 'saturn', '土卫二（恩克拉多斯）'],
  ['Tethys', 'saturn', '土卫三（忒堤斯）'],
  ['Dione', 'saturn', '土卫四（狄俄涅）'],
  ['Rhea', 'saturn', '土卫五（瑞亚）'],
  ['Titan', 'saturn', '土卫六（泰坦）'],
  ['Hyperion', 'saturn', '土卫七（许珀里翁）'],
  ['Iapetus', 'saturn', '土卫八（伊阿珀托斯）'],
  ['Miranda', 'uranus', '天卫五（米兰达）'],
  ['Ariel', 'uranus', '天卫一（艾瑞尔）'],
  ['Umbriel', 'uranus', '天卫二（乌姆柏里厄尔）'],
  ['Titania', 'uranus', '天卫三（泰坦尼亚）'],
  ['Oberon', 'uranus', '天卫四（奥伯龙）'],
  ['Triton', 'neptune', '海卫一（特里同）'],
  ['Proteus', 'neptune', '海卫八（普罗透斯）'],
  ['Charon', 'pluto', '冥卫一（卡戎）'],
];

const FRAME_MAP = { ecliptic: 'ecliptic', Laplace: 'laplace', equatorial: 'equator' };

const rows = [];
for (const [name, parent, nameZh, useLunarTheory] of SELECTION) {
  const s = sats[name];
  if (!s) throw new Error(`satellite not found in reference: ${name}`);
  const frame = FRAME_MAP[s.frame];
  if (!frame) throw new Error(`unknown frame "${s.frame}" for ${name}`);

  // (Ω, ω, M) at epoch -> (Ω, ϖ, L)
  const node = s.nodeDeg;
  const peri = s.nodeDeg + s.argPeriDeg;
  const L = node + s.argPeriDeg + s.meanAnomalyDeg;

  rows.push({
    name,
    nameZh,
    parent,
    frame,
    useLunarTheory: Boolean(useLunarTheory),
    jplCode: s.code,
    a: s.aKm / AU_KM,
    e: s.e,
    i: s.inclinationDeg,
    L,
    peri,
    node,
    period: s.periodDays,
    sourceA: s.aKm,
  });
}

const num = (v) => (Number.isInteger(v) ? String(v) : String(v));
const lines = [];
lines.push('// AUTO-GENERATED by scripts/gen-moon-orbits.mjs — do not edit by hand.');
lines.push('//');
lines.push('// Source: JPL "Planetary Satellite Mean Elements"');
lines.push('//   https://ssd.jpl.nasa.gov/sats/elem/');
lines.push('//   parsed copy: reference/satellite-elements.json');
lines.push('//');
lines.push('// Elements are mean osculating elements at epoch 2000-01-01.5 TDB (J2000).');
lines.push('// The `frame` field records the reference plane of the mean elements as');
lines.push('// published by JPL: "equator" = planet equator, "laplace" = Laplace plane');
lines.push('// (Solar approximates it with the planet equator), "ecliptic" = J2000');
lines.push('// ecliptic. The tabulated (Ω, ω, M) triple is stored as (Ω, ϖ, L) with');
lines.push('//   ϖ = ω + Ω,  L = ω + Ω + M.');
lines.push('');
lines.push("import type { OrbitalElements } from '../core/kepler';");
lines.push("import type { OrbitFrame } from './types';");
lines.push('');
lines.push('export interface MoonOrbitRecord {');
lines.push('  /** IAU satellite name. */');
lines.push('  name: string;');
lines.push('  /** Chinese name. */');
lines.push('  nameZh: string;');
lines.push('  /** Parent body id. */');
lines.push('  parent: string;');
lines.push('  /** JPL satellite code (e.g. 501 for Io). */');
lines.push('  jplCode: string;');
lines.push('  /** Reference plane of the mean elements. */');
lines.push('  frame: OrbitFrame;');
lines.push('  /** True when the perturbed lunar theory should be used instead. */');
lines.push('  useLunarTheory: boolean;');
lines.push('  /** Mean semi-major axis in kilometres, as published. */');
lines.push('  aKm: number;');
lines.push('  /** Elements, semi-major axis converted to AU. */');
lines.push('  orbit: OrbitalElements;');
lines.push('}');
lines.push('');
lines.push('export const MOON_ORBITS: MoonOrbitRecord[] = [');
for (const r of rows) {
  lines.push('  {');
  lines.push(`    name: ${JSON.stringify(r.name)},`);
  lines.push(`    nameZh: ${JSON.stringify(r.nameZh)},`);
  lines.push(`    parent: ${JSON.stringify(r.parent)},`);
  lines.push(`    jplCode: ${JSON.stringify(r.jplCode)},`);
  lines.push(`    frame: ${JSON.stringify(r.frame)},`);
  lines.push(`    useLunarTheory: ${r.useLunarTheory},`);
  lines.push(`    aKm: ${num(r.sourceA)},`);
  lines.push('    orbit: {');
  lines.push(`      epoch: ${J2000},`);
  lines.push(`      a: ${r.a},`);
  lines.push(`      e: ${r.e},`);
  lines.push(`      i: ${r.i},`);
  lines.push(`      L: ${r.L},`);
  lines.push(`      peri: ${r.peri},`);
  lines.push(`      node: ${r.node},`);
  lines.push(`      period: ${r.period},`);
  lines.push('    },');
  lines.push('  },');
}
lines.push('];');
lines.push('');

const outPath = resolve(ROOT, 'src/data/moon-orbits.generated.ts');
await writeFile(outPath, lines.join('\n'));
console.log(`Wrote ${rows.length} satellite orbits to ${outPath}`);
